template<typename T>
struct ContainerItem {
    T key;
    T value;
};

// Template Function Overloading for operator<
// Allows comparison between ContainerItems instantiated
// with potentially different, but comparable types (T1 vs T2)
template<typename T1, typename T2>
bool operator<(const ContainerItem<T1>& lhs,
               const ContainerItem<T2>& rhs)
{
    return lhs.key < rhs.key;
}
